if getgenv().AfterImageModuleRef then return end
local RunService=game:GetService("RunService") local Debris=game:GetService("Debris") local Players=game:GetService("Players")
local M={} M.__index=M M.GlobalCap=48
local DC={Duration=0.6,FadeStyle="Smooth",Interval=0.08,MaxImages=30,AntiStack=true,AntiStackDistance=0.5,Mode="OM",OM={fadein=0.08,fadeout=0.3,hold=nil,color=nil},Highlight=nil,HighlightFade=true,OverrideColor=nil,OverrideMaterial=nil,OverrideTransparency=0.3,VerticalDrift=0,Distortion=0,IgnoreParts={},IncludeAccessories=true,IncludeTools=false}
local FS={Smooth=function(p)return p end,Sudden=function(p)if p<0.7 then return 0 end return(p-0.7)/0.3 end,Flicker=function(p)if p>0.85 then return 1 end return(math.sin(p*math.pi*12)*0.5+0.5)*p end,Pulse=function(p)return math.clamp(p+math.sin(p*math.pi*4)*0.3,0,1)end,Shatter=function(p)if p<0.5 then return p*0.2 end return(p-0.5)*2 end,Reverse=function(p)if p<0.3 then return 0.5*(1-p/0.3)end return p end}
local function dm(b,o)local r={}for k,v in b do r[k]=v end if o then for k,v in o do r[k]=v end end return r end
local ST={Humanoid=true,Animator=true,Script=true,LocalScript=true,ModuleScript=true,Sound=true,ParticleEmitter=true,Trail=true,Beam=true,Fire=true,Smoke=true,Sparkles=true,Explosion=true,BillboardGui=true,SurfaceGui=true,ClickDetector=true,ProximityPrompt=true,ForceField=true,HumanoidDescription=true,Pathfinding=true}
local omG local function omI()if omG and omG.Parent then return end local p=Players.LocalPlayer if not p then return end omG=Instance.new("ScreenGui") omG.Name="ViewportUI" omG.ResetOnSpawn=false omG.Parent=p:WaitForChild("PlayerGui")end
local vPool={} local function gV()local v=table.remove(vPool)if v then return v end v=Instance.new("ViewportFrame")v.Name="AfterImage"v.Size=UDim2.new(1,0,1.1,0)v.AnchorPoint=Vector2.new(0,0.5)v.Position=UDim2.new(0,0,0.45,0)v.BackgroundTransparency=1 v.CurrentCamera=workspace.CurrentCamera return v end
local function fV(v)for _,c in v:GetChildren()do c:Destroy()end v.Parent=nil v.ImageColor3=Color3.new(1,1,1)v.LightColor=Color3.new(1,1,1)if#vPool<64 then vPool[#vPool+1]=v else v:Destroy()end end
local active={} local hbc local function sM()local now=os.clock()local n=#active local i=1 while i<=n do local rec=active[i]local vp=rec.vpf local rm=false if not vp.Parent then rm=true else local e=now-rec.t0 local nT if e>=rec.tout then fV(vp)rm=true elseif e<rec.tin then nT=1-(1-rec.baseT)*(e/rec.tin)elseif e<rec.thold then nT=rec.baseT else nT=rec.baseT+(1-rec.baseT)*((e-rec.thold)/(rec.tout-rec.thold))end if nT and(not rec.lastT or math.abs(nT-rec.lastT)>0.003)then vp.ImageTransparency=nT rec.lastT=nT end end if rm then active[i]=active[n]active[n]=nil n-=1 else i+=1 end end if n==0 and hbc then hbc:Disconnect()hbc=nil end end
local function reg(v,bT,ti,ho,to)ti=math.max(ti or 0.08,1/240)to=math.max(to or 0.3,1/240)ho=math.max(ho or 0,0)if#active>=M.GlobalCap then local vi=active[1]if vi then fV(vi.vpf)active[1]=active[#active]active[#active]=nil end end active[#active+1]={vpf=v,baseT=bT,t0=os.clock(),tin=ti,thold=ti+ho,tout=ti+ho+to}if not hbc then hbc=RunService.Heartbeat:Connect(sM)end end
local tC=setmetatable({},{__mode="k"})local lSP=setmetatable({},{__mode="k"})
local function aSO(tg,en,md)if not en then return true end local ok,pv=pcall(function()return tg:GetPivot().Position end)if not ok then return true end local l=lSP[tg]if l and(pv-l).Magnitude<(md or 0.75)then return false end lSP[tg]=pv return true end
local function sC(tg,iA,iT)local ar=tg.Archivable if not ar then tg.Archivable=true end local cl=tg:Clone()if not ar then tg.Archivable=ar end for _,d in cl:GetDescendants()do if ST[d.ClassName]then d:Destroy()elseif d:IsA("Accessory")then if not iA then d:Destroy()end elseif d:IsA("Tool")then if not iT then d:Destroy()end elseif d:IsA("JointInstance")or d:IsA("Constraint")or d:IsA("Attachment")then d:Destroy()elseif d:IsA("BasePart")then if d.Name=="HumanoidRootPart"then d:Destroy()else d.Anchored=true d.CanCollide=false d.CanQuery=false d.CanTouch=false d.CastShadow=false d.Massless=true end end end return cl end
local function pPa(pt,ro)local s={}local nd=pt while nd and nd~=ro do table.insert(s,1,nd.Name)nd=nd.Parent end return table.concat(s,"/")end
local function bT(tg,cfg)local iA,iT=cfg.IncludeAccessories,cfg.IncludeTools local tp=sC(tg,iA,iT)local lbp={}for _,d in tg:GetDescendants()do if d:IsA("BasePart")and d.Name~="HumanoidRootPart"then if(not iA)and d:FindFirstAncestorWhichIsA("Accessory")then continue end if(not iT)and d:FindFirstAncestorWhichIsA("Tool")then continue end lbp[pPa(d,tg)]=d end end local c=0 for _ in lbp do c+=1 end local rc={template=tp,liveByPath=lbp,partCount=c}tC[tg]=rc tg.Destroying:Once(function()if rc.template then rc.template:Destroy()rc.template=nil end tC[tg]=nil end)return rc end
local function lC(tg,iA,iT)local n=0 for _,d in tg:GetDescendants()do if d:IsA("BasePart")and d.Name~="HumanoidRootPart"then if(not iA)and d:FindFirstAncestorWhichIsA("Accessory")then continue end if(not iT)and d:FindFirstAncestorWhichIsA("Tool")then continue end n+=1 end end return n end
local function pC(tg,cfg)local iA,iT=cfg.IncludeAccessories,cfg.IncludeTools local rc=tC[tg]if rc and rc.template and rc.partCount~=lC(tg,iA,iT)then rc.template:Destroy()tC[tg]=nil rc=nil end if not rc or not rc.template then rc=bT(tg,cfg)end if not rc then return sC(tg,iA,iT)end local cl=rc.template:Clone()local lbp=rc.liveByPath for _,d in cl:GetDescendants()do if d:IsA("BasePart")then local lp=lbp[pPa(d,cl)]if lp and lp.Parent then d.CFrame=lp.CFrame d.Transparency=lp.Transparency d.Color=lp.Color d.Material=lp.Material end end end return cl end
local function spOM(tg,cfg)if not tg or not tg.Parent then return end omI()if not omG then return end local cl=pC(tg,cfg)for _,d in cl:GetDescendants()do if d:IsA("BasePart")and d.Transparency>=1 then d:Destroy()end end local vp=gV()local om=cfg.OM or{}local clr=om.color or cfg.OverrideColor if typeof(clr)=="Color3"then vp.ImageColor3=clr vp.LightColor=clr end vp.ImageTransparency=1 cl.Parent=vp vp.Parent=omG reg(vp,cfg.OverrideTransparency,om.fadein,om.hold or cfg.Duration,om.fadeout)return vp end
local function spSI(tg,cfg)if not tg or not tg.Parent then return end if cfg.Mode=="OM"then return spOM(tg,cfg)end local gM=Instance.new("Model")gM.Name="AfterImage"local uH=cfg.Mode=="Highlight"local parts={}if tg:IsA("Model")then for _,p in tg:GetDescendants()do if p:IsA("BasePart")then table.insert(parts,p)end end elseif tg:IsA("BasePart")then table.insert(parts,tg)end if#parts==0 then return end local gs,oT={},{}for _,pt in parts do if pt.Transparency>=1 then continue end if pt.Name=="HumanoidRootPart"then continue end local ok,g=pcall(function()return pt:Clone()end)if not ok or not g then continue end for _,c in g:GetDescendants()do if c:IsA("BasePart")or c:IsA("Script")or c:IsA("LocalScript")or c:IsA("ModuleScript")or c:IsA("Sound")or c:IsA("BodyMover")or c:IsA("ParticleEmitter")or c:IsA("Trail")or c:IsA("Beam")or c:IsA("BillboardGui")or c:IsA("SurfaceGui")or c:IsA("Weld")or c:IsA("WeldConstraint")or c:IsA("Motor6D")or c:IsA("Constraint")or c:IsA("Humanoid")or c:IsA("Animator")then c:Destroy()end end g.Anchored=true g.CanCollide=false g.CastShadow=false g.Massless=true g.CFrame=pt.CFrame if uH then g.Transparency=0 local hc=cfg.Highlight if typeof(hc)=="table"and hc.FillColor then g.Color=hc.FillColor elseif typeof(hc)=="Color3"then g.Color=hc else g.Color=Color3.new(0,0,0)end g.Material=Enum.Material.Neon else if cfg.OverrideColor then g.Color=cfg.OverrideColor end if cfg.OverrideMaterial then g.Material=cfg.OverrideMaterial end g.Transparency=cfg.OverrideTransparency end g.Parent=gM table.insert(gs,g)oT[g]=g.Transparency end if#gs==0 then return end gM.Parent=workspace local hl,hof,hoo=nil,1,1 if uH and cfg.Highlight then hl=Instance.new("Highlight")local hc=cfg.Highlight if typeof(hc)=="table"then hl.FillColor=hc.FillColor or Color3.new(0,0.5,1)hl.OutlineColor=hc.OutlineColor or Color3.new(0,0.7,1)hl.FillTransparency=hc.FillTransparency or 0.5 hl.OutlineTransparency=hc.OutlineTransparency or 0 hl.DepthMode=hc.DepthMode or Enum.HighlightDepthMode.Occluded elseif typeof(hc)=="Color3"then hl.FillColor=hc hl.OutlineColor=hc hl.FillTransparency=0.5 hl.OutlineTransparency=0 hl.DepthMode=Enum.HighlightDepthMode.Occluded end hof=hl.FillTransparency hoo=hl.OutlineTransparency hl.Parent=gM end local ff=FS[cfg.FadeStyle]or FS.Smooth local t0=os.clock()local cn cn=RunService.Heartbeat:Connect(function()local pr=math.clamp((os.clock()-t0)/cfg.Duration,0,1)local fv=ff(pr)for _,g in gs do if g and g.Parent then local bt=oT[g]or(uH and 0 or cfg.OverrideTransparency)g.Transparency=bt+(1-bt)*fv if cfg.VerticalDrift and cfg.VerticalDrift~=0 then g.CFrame=g.CFrame+Vector3.new(0,cfg.VerticalDrift*0.016,0)end if cfg.Distortion and cfg.Distortion>0 then local j=cfg.Distortion*(1-pr)g.CFrame=g.CFrame*CFrame.Angles((math.random()-0.5)*j*0.016,(math.random()-0.5)*j*0.016,(math.random()-0.5)*j*0.016)end end end if hl and hl.Parent and cfg.HighlightFade then hl.FillTransparency=hof+(1-hof)*fv hl.OutlineTransparency=hoo+(1-hoo)*fv end if pr>=1 then if cn then cn:Disconnect()end if gM and gM.Parent then gM:Destroy()end end end)Debris:AddItem(gM,cfg.Duration+1)return gM end
function M.Single(c)local mg=dm(DC,c)if not mg.Target then return end return spSI(mg.Target,mg)end
function M.Trail(c)local mg=dm(DC,c)if not mg.Target then return function()end end local run=true local ic=0 local om=mg.OM or{}local life=mg.Mode=="OM"and((om.fadein or 0.08)+(om.hold or mg.Duration)+(om.fadeout or 0.3))or mg.Duration task.spawn(function()while run do if ic<mg.MaxImages and aSO(mg.Target,mg.AntiStack,mg.AntiStackDistance)then ic+=1 spSI(mg.Target,mg)task.delay(life,function()ic-=1 end)end task.wait(mg.Interval)end end)return function()run=false end end
function M.Burst(c)local mg=dm(DC,c)if not mg.Target then return end local ct,sp=c.BurstCount or 5,c.BurstSpread or 0.05 for i=1,ct do task.delay(sp*(i-1),function()spSI(mg.Target,dm(mg,{OverrideTransparency=mg.OverrideTransparency+(i-1)*0.1,Duration=mg.Duration+(i-1)*0.1}))end)end end
function M.Dash(c)local mg=dm(DC,c)if not mg.Target then return function()end end local dc,di,df=c.DashCount or 8,c.DashInterval or 0.03,c.DashFade or 0.4 local run,sp=true,0 task.spawn(function()while run and sp<dc do sp+=1 local idx=sp spSI(mg.Target,dm(mg,{Duration=df+(idx*0.05),OverrideTransparency=mg.OverrideTransparency+(idx*0.03)}))task.wait(di)end end)return function()run=false end end
function M.Rainbow(c)local mg=dm(DC,c)if not mg.Target then return function()end end local run,h=true,0 local uH=mg.Mode=="Highlight" task.spawn(function()while run do h=(h+0.08)%1 local col=Color3.fromHSV(h,1,1)local rc if uH then rc=dm(mg,{Highlight={FillColor=col,OutlineColor=col,FillTransparency=0.3,OutlineTransparency=0,DepthMode=Enum.HighlightDepthMode.Occluded}})else rc=dm(mg,{OverrideColor=col,OverrideMaterial=mg.OverrideMaterial or Enum.Material.Neon})end if aSO(mg.Target,mg.AntiStack,mg.AntiStackDistance)then spSI(rc.Target,rc)end task.wait(mg.Interval)end end)return function()run=false end end
getgenv().AfterImageModuleRef = M
